using System.IO;
using System.Linq;
using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;
namespace Maracannes {
[InitializeOnLoad] public static class MapSafetySetup {
 const string B="Assets/Maracannes/Documentation/";static MapSafetySetup(){EditorApplication.update+=Run;}
 static void ColliderBox(Transform parent,string name,Vector3 position,Vector3 size){var g=new GameObject(name);g.transform.SetParent(parent,false);g.transform.position=position;g.isStatic=true;g.AddComponent<BoxCollider>().size=size;}
 public static void Apply(){EditorSceneManager.SaveOpenScenes();foreach(var path in new[]{AcervoTravel.Theater,AcervoTravel.Acervo}){var scene=EditorSceneManager.OpenScene(path,OpenSceneMode.Single);var old=scene.GetRootGameObjects().FirstOrDefault(g=>g.name=="Colisoes_Perimetro_Antiqueda");if(old)Object.DestroyImmediate(old);var floors=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Renderer>()).Where(r=>r.enabled&&(r.name.ToLower().Contains("piso")||r.name.StartsWith("Laje piso")||r.name.StartsWith("Calçada portuguesa")||r.name=="Faixa da rua")&&r.bounds.size.y<.8f&&r.bounds.size.x>2&&r.bounds.size.z>2).ToArray();if(floors.Length==0)throw new System.Exception("Pisos não identificados: "+path);var b=floors[0].bounds;foreach(var floor in floors){b.Encapsulate(floor.bounds);if(!floor.GetComponent<Collider>()){var mesh=floor.GetComponent<MeshFilter>();if(mesh&&mesh.sharedMesh){var box=floor.gameObject.AddComponent<BoxCollider>();box.center=mesh.sharedMesh.bounds.center;box.size=mesh.sharedMesh.bounds.size;}}}
 float x0=b.min.x-.6f,x1=b.max.x+.6f,z0=b.min.z-.6f,z1=b.max.z+.6f;var root=new GameObject("Colisoes_Perimetro_Antiqueda");var safety=root.AddComponent<MapSafetyBoundary>();safety.allowedBounds=new Bounds(new Vector3((x0+x1)/2,9,(z0+z1)/2),new Vector3(x1-x0,24,z1-z0));
 ColliderBox(root.transform,"Barreira externa esquerda",new Vector3(x0,9,(z0+z1)/2),new Vector3(.4f,24,z1-z0+.4f));ColliderBox(root.transform,"Barreira externa direita",new Vector3(x1,9,(z0+z1)/2),new Vector3(.4f,24,z1-z0+.4f));ColliderBox(root.transform,"Barreira externa frente",new Vector3((x0+x1)/2,9,z0),new Vector3(x1-x0+.4f,24,.4f));ColliderBox(root.transform,"Barreira externa fundo",new Vector3((x0+x1)/2,9,z1),new Vector3(x1-x0+.4f,24,.4f));ColliderBox(root.transform,"Laje de segurança sob o mapa",new Vector3((x0+x1)/2,-1,(z0+z1)/2),new Vector3(x1-x0,.4f,z1-z0));root.AddComponent<MapSafetyAudit>();EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);File.WriteAllText(B+"colisoes-"+(path==AcervoTravel.Acervo?"acervo":"teatro")+"-construcao.txt","Limites: "+safety.allowedBounds+"\n5 BoxColliders de segurança; pisos conferidos: "+floors.Length+"\nResgate abaixo de -0,5 m para último piso seguro; controlador existente preservado.");}
 AssetDatabase.SaveAssets();foreach(var p in new[]{"colisoes-acervo-runtime.txt","colisoes-teatro-runtime.txt"})if(File.Exists(B+p))File.Delete(B+p);File.WriteAllText(B+"colisoes-stage.request","0");}
 static void Run(){if(EditorApplication.isPlaying||EditorApplication.isCompiling||EditorApplication.isUpdating)return;const string marker=B+"colisoes-build.request";if(File.Exists(marker)){AssetDatabase.DeleteAsset(marker);Apply();return;}string file=B+"colisoes-stage.request";if(!File.Exists(file))return;string stage=File.ReadAllText(file).Trim();if(stage=="0"){File.WriteAllText(file,"1");EditorSceneManager.OpenScene(AcervoTravel.Acervo,OpenSceneMode.Single);EditorApplication.isPlaying=true;}else if(stage=="1"&&File.Exists(B+"colisoes-acervo-runtime.txt")){File.WriteAllText(file,"2");EditorSceneManager.OpenScene(AcervoTravel.Theater,OpenSceneMode.Single);EditorApplication.isPlaying=true;}else if(stage=="2"&&File.Exists(B+"colisoes-teatro-runtime.txt"))File.WriteAllText(file,"done");}
}
}
